18	// claudeImporter imports Claude Code transcripts (~/.claude/projects/<slug>/*.jsonl).
19	type claudeImporter struct{}
20	
21	func (claudeImporter) Name() string { return "claude-code" }
22	
23	func (claudeImporter) AgentType() types.AgentType { return agent.AgentTypeClaudeCode }
24	
25	// Discover returns Claude transcript files for the repo modified within the
26	// lookback window. overridePath replaces the default ~/.claude/projects/<slug>
27	// dir; sessionFilter, when non-empty, keeps only matching session IDs (the
28	// file stem).
29	func (claudeImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
30		dir := overridePath
31		if dir == "" {
32			ag := &claudecode.ClaudeCodeAgent{}
33			d, err := ag.GetSessionDir(repoRoot)
34			if err != nil {
35				return nil, fmt.Errorf("resolve claude session dir: %w", err)
36			}
37			dir = d
38		}
39		entries, err := os.ReadDir(dir)
40		if err != nil {
41			if os.IsNotExist(err) {
42				return nil, nil // no transcripts for this repo
43			}
44			return nil, fmt.Errorf("read claude session dir: %w", err)
45		}
46		cutoff := now.AddDate(0, 0, -LookbackDays)
47		var out []SessionFile
48		for _, e := range entries {
49			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
50				continue
51			}
52			stem := strings.TrimSuffix(e.Name(), ".jsonl")
53			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, stem) {
54				continue
55			}
56			info, err := e.Info()
57			if err != nil {
58				continue
59			}
60			if info.ModTime().Before(cutoff) {
61				continue
62			}
63			out = append(out, SessionFile{Path: filepath.Join(dir, e.Name()), SessionID: stem})
64		}
65		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
66		return out, nil
67	}
