11	func TestClaudeDiscover_LookbackAndFilter(t *testing.T) {
12		t.Parallel()
13		dir := t.TempDir()
14		now := time.Date(2026, 6, 25, 12, 0, 0, 0, time.UTC)
15		writeAged := func(name string, age time.Duration) {
16			p := filepath.Join(dir, name)
17			if err := os.WriteFile(p, []byte("{}\n"), 0o644); err != nil {
18				t.Fatal(err)
19			}
20			mt := now.Add(-age)
21			if err := os.Chtimes(p, mt, mt); err != nil {
22				t.Fatal(err)
23			}
24		}
25		writeAged("recent.jsonl", 5*24*time.Hour)
26		writeAged("old.jsonl", 60*24*time.Hour)
27		writeAged("skip.txt", 1*time.Hour)
28	
29		imp := claudeImporter{}
30		got, err := imp.Discover("", dir, now, nil)
31		if err != nil {
32			t.Fatal(err)
33		}
34		if len(got) != 1 || got[0].SessionID != "recent" {
35			t.Fatalf("lookback filter wrong: %v", got)
36		}
37	
38		writeAged("abc123.jsonl", 1*24*time.Hour)
39		got, err = imp.Discover("", dir, now, []string{"abc123"})
40		if err != nil {
41			t.Fatal(err)
42		}
43		if len(got) != 1 || got[0].SessionID != "abc123" {
44			t.Fatalf("session filter wrong: %v", got)
45		}
46	}
