59	func TestClaudeSplitTurns_TwoPromptsBoundedByNext(t *testing.T) {
60		t.Parallel()
61		full := []byte(strings.Join([]string{
62			`{"type":"user","uuid":"u1","parentUuid":"","timestamp":"2026-06-20T00:00:00Z","message":{"role":"user","content":"first"}}`,
63			`{"type":"assistant","uuid":"a1","message":{"id":"m1","model":"claude-x","content":[{"type":"text","text":"ok"}],"usage":{"input_tokens":10,"output_tokens":5}}}`,
64			`{"type":"user","uuid":"u2","parentUuid":"a1","timestamp":"2026-06-20T00:01:00Z","message":{"role":"user","content":"second"}}`,
65			`{"type":"assistant","uuid":"a2","message":{"id":"m2","model":"claude-x","content":[{"type":"text","text":"done"}],"usage":{"input_tokens":20,"output_tokens":7}}}`,
66		}, "\n") + "\n")
67	
68		turns, err := claudeImporter{}.SplitTurns(SessionFile{Path: filepath.Join(t.TempDir(), "s.jsonl"), SessionID: "s"}, full)
69		if err != nil {
70			t.Fatal(err)
71		}
72		if len(turns) != 2 {
73			t.Fatalf("want 2 turns, got %d", len(turns))
74		}
75		if turns[0].LineStart != 0 || turns[0].LineEnd != 2 {
76			t.Errorf("turn0 bounds = [%d,%d), want [0,2)", turns[0].LineStart, turns[0].LineEnd)
77		}
78		if turns[0].Prompt != "first" || turns[1].Prompt != "second" {
79			t.Errorf("prompts = %q,%q", turns[0].Prompt, turns[1].Prompt)
80		}
81		if turns[0].Model != "claude-x" {
82			t.Errorf("turn0 model = %q, want claude-x", turns[0].Model)
83		}
84		if turns[0].Tokens == nil || turns[0].Tokens.OutputTokens != 5 {
85			t.Errorf("turn0 tokens not bounded to its own turn: %+v", turns[0].Tokens)
86		}
87		if turns[1].Tokens == nil || turns[1].Tokens.OutputTokens != 7 {
88			t.Errorf("turn1 tokens wrong: %+v", turns[1].Tokens)
89		}
