19	func TestDeriveCheckpointID_StableAndDistinct(t *testing.T) {
20		t.Parallel()
21		a := DeriveCheckpointID("sess", "turn-1")
22		b := DeriveCheckpointID("sess", "turn-1")
23		c := DeriveCheckpointID("sess", "turn-2")
24		if a != b {
25			t.Errorf("not deterministic: %s != %s", a, b)
26		}
27		if a == c {
28			t.Errorf("collision across turns: %s == %s", a, c)
29		}
30		if a.IsEmpty() {
