77	// ResolveSessionFile returns the path to a Cursor session file.
78	// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
79	// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
80	// We prefer nested if the file OR directory exists (the directory may be created
81	// before the file is flushed), otherwise fall back to flat.
82	func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
83		nestedDir := filepath.Join(sessionDir, agentSessionID)
84		nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
85		if _, err := os.Stat(nested); err == nil {
86			return nested
87		}
88		// IDE creates the directory before the transcript file — predict nested path.
89		if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
90			return nested
91		}
92		return filepath.Join(sessionDir, agentSessionID+".jsonl")
93	}
